// apps/web/lib/playerService.ts

import { db } from "./firebase";
import {
  collection,
  addDoc,
  getDocs,
  deleteDoc,
  doc,
} from "firebase/firestore";

const PLAYERS_COLLECTION = "players";

/**
 * Add a new player
 */
export async function addPlayer(name: string) {
  if (!name.trim()) throw new Error("Player name is required");

  const docRef = await addDoc(collection(db, PLAYERS_COLLECTION), {
    name: name.trim(),
    createdAt: new Date().toISOString(),
    active: true,
  });

  return docRef.id;
}

/**
 * Get all players
 */
export async function getPlayers() {
  const snapshot = await getDocs(collection(db, PLAYERS_COLLECTION));

  return snapshot.docs.map((doc) => ({
    id: doc.id,
    ...doc.data(),
  }));
}

/**
 * Delete a player
 */
export async function deletePlayer(playerId: string) {
  await deleteDoc(doc(db, PLAYERS_COLLECTION, playerId));
}