// apps/web/lib/sessionService.ts

import { db } from "./firebase";
import {
  collection,
  addDoc,
  getDocs,
  doc,
  getDoc,
  updateDoc,
  arrayUnion,
} from "firebase/firestore";

const SESSIONS_COLLECTION = "sessions";

/**
 * Create a new poker session
 */
export async function createSession(date: string) {
  const docRef = await addDoc(collection(db, SESSIONS_COLLECTION), {
    date,
    players: [],
    createdAt: new Date().toISOString(),
    status: "active", // active | closed
  });

  return docRef.id;
}

/**
 * Get all sessions
 */
export async function getSessions() {
  const snapshot = await getDocs(collection(db, SESSIONS_COLLECTION));

  return snapshot.docs.map((doc) => ({
    id: doc.id,
    ...doc.data(),
  }));
}

/**
 * Get single session by ID
 */
export async function getSession(sessionId: string) {
  const ref = doc(db, SESSIONS_COLLECTION, sessionId);
  const snap = await getDoc(ref);

  if (!snap.exists()) throw new Error("Session not found");

  return {
    id: snap.id,
    ...snap.data(),
  };
}

/**
 * Add player to a session
 */
export async function addPlayerToSession(
  sessionId: string,
  playerId: string
) {
  const ref = doc(db, SESSIONS_COLLECTION, sessionId);

  await updateDoc(ref, {
    players: arrayUnion(playerId),
  });
}